@push('styles')
<style>
.battery-view{max-width:none;min-width:0}.battery-view .battery-head{display:flex;justify-content:space-between;gap:14px;align-items:center;flex-wrap:wrap}.battery-view .battery-list{list-style:none;padding:0;margin:15px 0}.battery-view .battery-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:16px;border-top:1px solid var(--border-color,#ddd);padding:14px 0;align-items:center}.battery-view .battery-row strong{font-size:13px;overflow-wrap:anywhere;display:block}.battery-view .battery-row small{display:block;margin-top:5px;color:var(--text-muted,#64748b);font-size:12px}.battery-view .actions form{margin:0}.battery-view .cta{display:inline-flex;align-items:center;justify-content:center;min-height:42px;text-decoration:none}.battery-view .remove{border:1px solid #dc8e8e;background:transparent;color:#b32626}.dark-mode .battery-view .remove{color:#ffb5b5}.battery-view label{line-height:1.5}.battery-view .fields>*{min-width:0}.battery-view input{box-sizing:border-box}.battery-view h2{font-size:19px}.battery-view h3{font-size:16px}.battery-view :focus-visible{outline:3px solid #458bef;outline-offset:3px}.battery-view .pdf-frame{width:100%;height:65vh;min-height:360px;border:1px solid var(--border-color,#ddd);border-radius:10px;margin:12px 0}.battery-view .battery-events{list-style:none;padding:0;font-size:12px}.battery-view .battery-events li{border-top:1px solid var(--border-color,#ddd);padding:10px 0}.battery-view .status-valid{color:#167347}.dark-mode .battery-view .status-valid{color:#9be5bf}@media(max-width:700px){.battery-view .battery-row{grid-template-columns:1fr}.battery-view .cta{min-height:44px}.battery-view .actions{gap:8px}.battery-view .panel{padding:15px}.battery-view .fields{grid-template-columns:1fr}}
.battery-view .cta:disabled{opacity:.45;cursor:not-allowed}.battery-view .muted{color:var(--text-muted,#64748b)}
</style>
@endpush
